<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Pobrecita — Photo Gallery</title>
  <style>
    :root {
      --bg: #fff7f5;
      --text: #3b2a28;
      --accent: #d68080;
      --card: #ffffff;
      --shadow: rgba(59, 42, 40, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
    }

    header {
      text-align: center;
      padding: 3rem 1rem 2rem;
    }

    header h1 {
      margin: 0;
      font-size: 2.8rem;
      letter-spacing: -0.03em;
      color: var(--accent);
    }

    header p {
      margin: 0.5rem 0 0;
      font-size: 1.1rem;
      opacity: 0.85;
    }

    .gallery {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
      gap: 1.25rem;
      max-width: 1200px;
      margin: 0 auto;
      padding: 1rem 1.5rem 4rem;
    }

    .photo {
      position: relative;
      overflow: hidden;
      border-radius: 1rem;
      background: var(--card);
      box-shadow: 0 4px 12px var(--shadow);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    .photo:hover,
    .photo:focus-within {
      transform: translateY(-4px);
      box-shadow: 0 8px 24px var(--shadow);
    }

    .photo img {
      display: block;
      width: 100%;
      height: 220px;
      object-fit: cover;
      transition: transform 0.3s ease;
    }

    .photo:hover img {
      transform: scale(1.05);
    }

    .photo figcaption {
      padding: 0.85rem 1rem;
      font-size: 0.95rem;
      font-weight: 500;
      text-align: center;
    }

    /* Lightbox */
    .lightbox {
      position: fixed;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      background: rgba(59, 42, 40, 0.92);
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.25s ease;
      z-index: 1000;
    }

    .lightbox.active {
      opacity: 1;
      pointer-events: auto;
    }

    .lightbox img {
      max-width: 90vw;
      max-height: 80vh;
      border-radius: 0.75rem;
      box-shadow: 0 12px 40px rgba(0, 0, 0, 0.35);
    }

    .lightbox-caption {
      position: absolute;
      bottom: 1.5rem;
      left: 50%;
      transform: translateX(-50%);
      color: #fff;
      font-size: 1.1rem;
      text-align: center;
      padding: 0.5rem 1rem;
      background: rgba(0, 0, 0, 0.4);
      border-radius: 2rem;
      max-width: 80vw;
    }

    .close,
    .prev,
    .next {
      position: absolute;
      background: rgba(255, 255, 255, 0.15);
      color: #fff;
      border: none;
      cursor: pointer;
      border-radius: 50%;
      width: 3rem;
      height: 3rem;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
      transition: background 0.2s ease;
      user-select: none;
    }

    .close:hover,
    .prev:hover,
    .next:hover {
      background: rgba(255, 255, 255, 0.3);
    }

    .close {
      top: 1rem;
      right: 1rem;
    }

    .prev {
      left: 1rem;
      top: 50%;
      transform: translateY(-50%);
    }

    .next {
      right: 1rem;
      top: 50%;
      transform: translateY(-50%);
    }

    footer {
      text-align: center;
      padding: 2rem 1rem 3rem;
      font-size: 0.9rem;
      opacity: 0.7;
    }

    @media (max-width: 600px) {
      header h1 {
        font-size: 2rem;
      }

      .gallery {
        grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
        gap: 0.75rem;
        padding: 1rem 1rem 2rem;
      }

      .photo img {
        height: 150px;
      }

      .prev,
      .next {
        display: none;
      }
    }
  </style>
</head>
<body>
  <header>
    <h1>Pobrecita</h1>
    <p>A little photo gallery of moments, memories, and soft light.</p>
  </header>

  <main class="gallery" id="gallery">
    <figure class="photo" data-index="0" tabindex="0">
      <img src="https://picsum.photos/id/10/800/600" alt="Morning light through the trees" loading="lazy" />
      <figcaption>Morning hush</figcaption>
    </figure>
    <figure class="photo" data-index="1" tabindex="0">
      <img src="https://picsum.photos/id/28/800/600" alt="A winding path in the forest" loading="lazy" />
      <figcaption>Forest path</figcaption>
    </figure>
    <figure class="photo" data-index="2" tabindex="0">
      <img src="https://picsum.photos/id/35/800/600" alt="City rooftops at dusk" loading="lazy" />
      <figcaption>Dusk skyline</figcaption>
    </figure>
    <figure class="photo" data-index="3" tabindex="0">
      <img src="https://picsum.photos/id/41/800/600" alt="Calm ocean waves" loading="lazy" />
      <figcaption>Quiet tide</figcaption>
    </figure>
    <figure class="photo" data-index="4" tabindex="0">
      <img src="https://picsum.photos/id/49/800/600" alt="Mountain peaks above the clouds" loading="lazy" />
      <figcaption>Above the clouds</figcaption>
    </figure>
    <figure class="photo" data-index="5" tabindex="0">
      <img src="https://picsum.photos/id/58/800/600" alt="A cozy table with coffee" loading="lazy" />
      <figcaption>Sunday morning</figcaption>
    </figure>
    <figure class="photo" data-index="6" tabindex="0">
      <img src="https://picsum.photos/id/76/800/600" alt="Golden wheat field" loading="lazy" />
      <figcaption>Golden hour</figcaption>
    </figure>
    <figure class="photo" data-index="7" tabindex="0">
      <img src="https://picsum.photos/id/88/800/600" alt="Snow-covered cabin" loading="lazy" />
      <figcaption>Winter stillness</figcaption>
    </figure>
    <figure class="photo" data-index="8" tabindex="0">
      <img src="https://picsum.photos/id/101/800/600" alt="Blooming garden flowers" loading="lazy" />
      <figcaption>Garden bloom</figcaption>
    </figure>
  </main>

  <div class="lightbox" id="lightbox" aria-hidden="true" role="dialog" aria-label="Image lightbox">
    <button class="close" aria-label="Close lightbox">&times;</button>
    <button class="prev" aria-label="Previous image">&#10094;</button>
    <img src="" alt="" id="lightbox-img" />
    <div class="lightbox-caption" id="lightbox-caption"></div>
    <button class="next" aria-label="Next image">&#10095;</button>
  </div>

  <footer>
    Made with care for Pobrecita.
  </footer>

  <script>
    (function () {
      const photos = Array.from(document.querySelectorAll('.photo'));
      const lightbox = document.getElementById('lightbox');
      const lightboxImg = document.getElementById('lightbox-img');
      const lightboxCaption = document.getElementById('lightbox-caption');
      const closeBtn = lightbox.querySelector('.close');
      const prevBtn = lightbox.querySelector('.prev');
      const nextBtn = lightbox.querySelector('.next');

      let currentIndex = 0;

      function openLightbox(index) {
        currentIndex = index;
        updateLightbox();
        lightbox.classList.add('active');
        lightbox.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
      }

      function closeLightbox() {
        lightbox.classList.remove('active');
        lightbox.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
      }

      function updateLightbox() {
        const photo = photos[currentIndex];
        const img = photo.querySelector('img');
        const caption = photo.querySelector('figcaption').textContent;
        lightboxImg.src = img.src.replace(/\/800\/600$/, '/1200/900');
        lightboxImg.alt = img.alt;
        lightboxCaption.textContent = caption;
      }

      function nextImage() {
        currentIndex = (currentIndex + 1) % photos.length;
        updateLightbox();
      }

      function prevImage() {
        currentIndex = (currentIndex - 1 + photos.length) % photos.length;
        updateLightbox();
      }

      photos.forEach((photo, index) => {
        photo.addEventListener('click', () => openLightbox(index));
        photo.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            openLightbox(index);
          }
        });
      });

      closeBtn.addEventListener('click', closeLightbox);
      nextBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        nextImage();
      });
      prevBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        prevImage();
      });

      lightbox.addEventListener('click', (e) => {
        if (e.target === lightbox || e.target === lightboxImg) {
          closeLightbox();
        }
      });

      document.addEventListener('keydown', (e) => {
        if (!lightbox.classList.contains('active')) return;
        if (e.key === 'Escape') closeLightbox();
        if (e.key === 'ArrowRight') nextImage();
        if (e.key === 'ArrowLeft') prevImage();
      });
    })();
  </script>
</body>
</html>
